package com.metaverse.coin.strategy.core.arbitrage.multi;
import java.math.BigDecimal; import java.math.RoundingMode; import java.time.Instant; import java.util.*; import java.util.function.Function; import java.util.stream.Collectors;
public class CrossExchangePositionMonitorService {
 private final Map<Exchange,CrossExchangeMarketDataProvider> providers; private final CrossExchangeRiskService risk; private final CrossExchangePaperTradingService paper; private final CrossExchangeArbitragePersistenceService persistence;
 public CrossExchangePositionMonitorService(List<CrossExchangeMarketDataProvider> p,CrossExchangeRiskService r,CrossExchangePaperTradingService t){this(p,r,t,null);}
 public CrossExchangePositionMonitorService(List<CrossExchangeMarketDataProvider> p,CrossExchangeRiskService r,CrossExchangePaperTradingService t,CrossExchangeArbitragePersistenceService persistence){providers=p.stream().collect(Collectors.toMap(CrossExchangeMarketDataProvider::exchange,Function.identity()));risk=r;paper=t;this.persistence=persistence;}
 public List<PaperHedgePosition> monitor(Instant now){List<PaperHedgePosition> closed=new ArrayList<>();for(PaperHedgePosition p:new ArrayList<>(paper.positions())){if(p.status()==PaperHedgePosition.Status.MANUAL_INTERVENTION){var naked=risk.nakedExposure(p,now);if(naked.passed()){paper.openCircuit();if(persistence!=null)persistence.saveRisk(p.positionId(),p.opportunity().opportunityId(),"NAKED_EXPOSURE",false,naked.reason());}continue;}if(p.status()!=PaperHedgePosition.Status.OPENED)continue;try{var l=providers.get(p.opportunity().longQuote().exchange()).fundingRate(p.opportunity().symbol());var s=providers.get(p.opportunity().shortQuote().exchange()).fundingRate(p.opportunity().symbol());BigDecimal latest=s.hourlyFundingRate().subtract(l.hourlyFundingRate());BigDecimal deviation=s.markPrice().subtract(l.markPrice()).abs().divide(l.markPrice(),12,RoundingMode.HALF_UP);var exit=risk.shouldExit(p,latest,deviation,now,true,paper.isPaused());if(exit.passed())closed.add(paper.close(p.positionId(),now));}catch(RuntimeException e){var exit=risk.shouldExit(p,BigDecimal.ZERO,BigDecimal.ZERO,now,false,paper.isPaused());if(exit.passed())closed.add(paper.close(p.positionId(),now));}}return closed;}
}
